"""Validate artifacts generated by the actual synthetic integration run."""
import json
from pathlib import Path
from pykt.benchmark.runtime import read,rows,complete
from pykt.benchmark.metrics import validate_pair


def check_run(root):
    root=Path(root);tasks=read(root/'task_manifest.json')
    for task in tasks:
        assert complete(task)
        rs=rows(Path(task['output_dir'])/'predictions_test.jsonl.gz')
        uids={r['student_id'] for r in rs}
        for uid in uids:
            events=[r for r in rs if r['student_id']==uid]
            assert [r['event_index'] for r in events]==list(range(9))
            assert [r['input_history_length'] for r in events]==[0,1,2,3,4,5,6,7,4]
        assert all(0<=r['predicted_probability']<=1 for r in rs)
    for a,b in zip(tasks[::2],tasks[1::2]):
        validate_pair(rows(Path(a['output_dir'])/'predictions_test.jsonl.gz'),rows(Path(b['output_dir'])/'predictions_test.jsonl.gz'))


if __name__=='__main__':
    import sys
    check_run(sys.argv[1])
